import sys
from collections import deque

def bfs(n, m, k, grid):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    start = None
    end = None

    # Find the positions of 'S' and 'T'
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                end = (i, j)

    # BFS initialization
    queue = deque([(start, 0, set(), '')])
    visited = set()
    visited.add(start)

    while queue:
        (x, y), dist, types, path = queue.popleft()

        # If we reach 'T', return the path
        if (x, y) == end:
            return path

        # Explore neighbors
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                new_type = grid[nx][ny]
                if new_type != 'S' and new_type != 'T':
                    new_types = types | {new_type}
                    if len(new_types) <= k:
                        new_path = path + new_type
                        if (nx, ny, frozenset(new_types)) not in visited:
                            visited.add((nx, ny, frozenset(new_types)))
                            queue.append(((nx, ny), dist + 1, new_types, new_path))

    return '-1'

# Read input
n, m, k = map(int, sys.stdin.readline().split())
grid = [sys.stdin.readline().strip() for _ in range(n)]

# Output the result
print(bfs(n, m, k, grid))
